<?php
header('Content-Type: application/json');header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE');header('Access-Control-Allow-Headers: Content-Type, Authorization');if(session_status()===PHP_SESSION_NONE)session_start();require_once '../config.php';require_once '../database.php';require_once '../auth.php';$db=new Database();$auth=new Auth($db);$pdo=$db->getConnection();if(!$auth->isLoggedIn()){http_response_code(401);echo json_encode(['error'=>'غير مصرح بالوصول']);exit;}$method=$_SERVER['REQUEST_METHOD'];$action=$_GET['action']??'';try{switch($method){case 'GET':handleGetRequest($action,$pdo);break;case 'POST':handlePostRequest($action,$pdo);break;case 'PUT':handlePutRequest($action,$pdo);break;default:http_response_code(405);echo json_encode(['error'=>'طريقة غير مدعومة']);}}catch(Exception $e){http_response_code(500);echo json_encode(['error'=>$e->getMessage()]);}
function handleGetRequest($a,$pdo){switch($a){case 'history':getTrackingHistory($pdo);break;case 'current_status':getCurrentStatus($pdo);break;case 'locations':getLocations($pdo);break;case 'devices':getDevices($pdo);break;case 'analytics':getTrackingAnalytics($pdo);break;case 'realtime':getRealtimeTracking($pdo);break;default:http_response_code(400);echo json_encode(['error'=>'إجراء غير صحيح']);}}
function handlePostRequest($a,$pdo){$i=json_decode(file_get_contents('php://input'),true);switch($a){case 'scan':scanBaggage($pdo,$i);break;case 'update_location':updateLocation($pdo,$i);break;case 'bulk_scan':bulkScanBaggage($pdo,$i);break;default:http_response_code(400);echo json_encode(['error'=>'إجراء غير صحيح']);}}
function handlePutRequest($a,$pdo){$i=json_decode(file_get_contents('php://input'),true);if($a==='update_status')updateTrackingStatus($pdo,$i);else{http_response_code(400);echo json_encode(['error'=>'إجراء غير صحيح']);}}
function getTrackingHistory($pdo){$id=$_GET['baggage_id']??'';$limit=max(1,min(100,(int)($_GET['limit']??50)));if(empty($id)){http_response_code(400);echo json_encode(['error'=>'معرف الأمتعة مطلوب']);return;}$s=$pdo->prepare("SELECT tl.*,u.full_name as staff_name,l.location_name,l.location_type,d.device_name,d.device_type FROM tracking_logs tl LEFT JOIN users u ON tl.scanned_by=u.id LEFT JOIN locations l ON tl.location_id=l.id LEFT JOIN devices d ON tl.device_id=d.id WHERE tl.baggage_id=? ORDER BY tl.actual_scan_time DESC LIMIT ?");$s->execute([$id,$limit]);$h=$s->fetchAll(PDO::FETCH_ASSOC);echo json_encode(['success'=>true,'data'=>$h,'count'=>count($h)]);}
function getCurrentStatus($pdo){$id=$_GET['baggage_id']??'';if(empty($id)){http_response_code(400);echo json_encode(['error'=>'معرف الأمتعة مطلوب']);return;}$s=$pdo->prepare("SELECT b.*,u.full_name as passenger_name,f.flight_number,a1.airport_name as origin_airport,a2.airport_name as destination_airport,bt.type_name as baggage_type_name FROM baggage b JOIN users u ON b.passenger_id=u.id JOIN flights f ON b.flight_id=f.id JOIN airports a1 ON f.origin_airport_id=a1.id JOIN airports a2 ON f.destination_airport_id=a2.id JOIN baggage_types bt ON b.baggage_type_id=bt.id WHERE b.id=?");$s->execute([$id]);$b=$s->fetch(PDO::FETCH_ASSOC);if(!$b){http_response_code(404);echo json_encode(['error'=>'لم يتم العثور على الأمتعة']);return;}$s=$pdo->prepare("SELECT tl.*,l.location_name,l.location_type FROM tracking_logs tl LEFT JOIN locations l ON tl.location_id=l.id WHERE tl.baggage_id=? ORDER BY tl.actual_scan_time DESC LIMIT 1");$s->execute([$id]);echo json_encode(['success'=>true,'baggage'=>$b,'current_location'=>$s->fetch(PDO::FETCH_ASSOC),'status'=>$b['status']]);}
function getLocations($pdo){$type=$_GET['type']??'';$status=$_GET['status']??'active';$where='WHERE status = ?';$p=[$status];if($type!==''){$where.=' AND location_type = ?';$p[]=$type;}$s=$pdo->prepare("SELECT * FROM locations $where ORDER BY location_name");$s->execute($p);echo json_encode(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}
function getDevices($pdo){$type=$_GET['type']??'';$status=$_GET['status']??'';$loc=$_GET['location_id']??'';$where='WHERE 1=1';$p=[];if($type!==''){$where.=' AND device_type = ?';$p[]=$type;}if($status!==''){$where.=' AND status = ?';$p[]=$status;}if($loc!==''){$where.=' AND location_id = ?';$p[]=$loc;}$s=$pdo->prepare("SELECT d.*,l.location_name FROM devices d LEFT JOIN locations l ON d.location_id=l.id $where ORDER BY d.device_name");$s->execute($p);echo json_encode(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}
function getTrackingAnalytics($pdo){$period=$_GET['period']??'today';$airline=$_GET['airline_id']??'';$airport=$_GET['airport_id']??'';switch($period){case 'week':$date="tl.actual_scan_time >= DATE_SUB(NOW(), INTERVAL 7 DAY)";break;case 'month':$date="tl.actual_scan_time >= DATE_SUB(NOW(), INTERVAL 30 DAY)";break;default:$date="DATE(tl.actual_scan_time)=CURDATE()";}$where="WHERE $date";$p=[];if($airline!==''){$where.=' AND f.airline_id = ?';$p[]=$airline;}if($airport!==''){$where.=' AND (f.origin_airport_id = ? OR f.destination_airport_id = ?)';$p[]=$airport;$p[]=$airport;}$s=$pdo->prepare("SELECT COUNT(*) as total_scans,COUNT(DISTINCT tl.baggage_id) as unique_baggage,COUNT(DISTINCT tl.scanned_by) as active_staff FROM tracking_logs tl JOIN baggage b ON tl.baggage_id=b.id JOIN flights f ON b.flight_id=f.id $where");$s->execute($p);$general=$s->fetch(PDO::FETCH_ASSOC);$s=$pdo->prepare("SELECT tl.status,COUNT(*) as count FROM tracking_logs tl JOIN baggage b ON tl.baggage_id=b.id JOIN flights f ON b.flight_id=f.id $where GROUP BY tl.status ORDER BY count DESC");$s->execute($p);$byStatus=$s->fetchAll(PDO::FETCH_ASSOC);$s=$pdo->prepare("SELECT l.location_name,l.location_type,COUNT(*) as count FROM tracking_logs tl JOIN baggage b ON tl.baggage_id=b.id JOIN flights f ON b.flight_id=f.id LEFT JOIN locations l ON tl.location_id=l.id $where GROUP BY l.id,l.location_name,l.location_type ORDER BY count DESC LIMIT 10");$s->execute($p);$byLocation=$s->fetchAll(PDO::FETCH_ASSOC);$s=$pdo->prepare("SELECT d.device_type,COUNT(*) as count FROM tracking_logs tl JOIN baggage b ON tl.baggage_id=b.id JOIN flights f ON b.flight_id=f.id LEFT JOIN devices d ON tl.device_id=d.id $where GROUP BY d.device_type ORDER BY count DESC");$s->execute($p);echo json_encode(['success'=>true,'data'=>['general'=>$general,'by_status'=>$byStatus,'by_location'=>$byLocation,'by_device'=>$s->fetchAll(PDO::FETCH_ASSOC)],'period'=>$period]);}
function getRealtimeTracking($pdo){$limit=max(1,min(100,(int)($_GET['limit']??20)));$s=$pdo->prepare("SELECT tl.*,b.baggage_code,u.full_name as passenger_name,f.flight_number,l.location_name,d.device_name,staff.full_name as staff_name FROM tracking_logs tl JOIN baggage b ON tl.baggage_id=b.id JOIN users u ON b.passenger_id=u.id JOIN flights f ON b.flight_id=f.id LEFT JOIN locations l ON tl.location_id=l.id LEFT JOIN devices d ON tl.device_id=d.id LEFT JOIN users staff ON tl.scanned_by=staff.id WHERE tl.actual_scan_time >= DATE_SUB(NOW(),INTERVAL 1 HOUR) ORDER BY tl.actual_scan_time DESC LIMIT ?");$s->execute([$limit]);echo json_encode(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC),'timestamp'=>date('Y-m-d H:i:s')]);}
function scanBaggage($pdo,$i){foreach(['baggage_id','location_id','status'] as $f){if(!isset($i[$f])||empty($i[$f])){http_response_code(400);echo json_encode(['error'=>"الحقل $f مطلوب"]);return;}}try{$pdo->beginTransaction();$s=$pdo->prepare("UPDATE baggage SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?");$s->execute([$i['status'],$i['baggage_id']]);$s=$pdo->prepare("INSERT INTO tracking_logs (baggage_id,location_id,status,remarks,scanned_by,device_id,scan_type,gps_latitude,gps_longitude,actual_scan_time) VALUES (?,?,?,?,?,?,?,?,?,NOW())");$s->execute([$i['baggage_id'],$i['location_id'],$i['status'],$i['remarks']??'',$_SESSION['user_id'],$i['device_id']??null,$i['scan_type']??'manual',$i['gps_latitude']??null,$i['gps_longitude']??null]);$id=$pdo->lastInsertId();if(!empty($i['device_id'])){$s=$pdo->prepare("UPDATE devices SET last_seen=NOW(),status='online' WHERE id=?");$s->execute([$i['device_id']]);}$pdo->commit();echo json_encode(['success'=>true,'message'=>'تم مسح الأمتعة بنجاح','tracking_id'=>$id]);}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo json_encode(['error'=>'خطأ في مسح الأمتعة: '.$e->getMessage()]);}}
function updateLocation($pdo,$i){foreach(['baggage_id','location_id'] as $f){if(!isset($i[$f])||empty($i[$f])){http_response_code(400);echo json_encode(['error'=>"الحقل $f مطلوب"]);return;}}try{$s=$pdo->prepare("SELECT status FROM baggage WHERE id=?");$s->execute([$i['baggage_id']]);$b=$s->fetch();if(!$b){http_response_code(404);echo json_encode(['error'=>'لم يتم العثور على الأمتعة']);return;}$s=$pdo->prepare("INSERT INTO tracking_logs (baggage_id,location_id,status,remarks,scanned_by,device_id,scan_type,gps_latitude,gps_longitude,actual_scan_time) VALUES (?,?,?,?,?,?,?,?,?,NOW())");$s->execute([$i['baggage_id'],$i['location_id'],$b['status'],$i['remarks']??'تحديث موقع',$_SESSION['user_id'],$i['device_id']??null,$i['scan_type']??'manual',$i['gps_latitude']??null,$i['gps_longitude']??null]);echo json_encode(['success'=>true,'message'=>'تم تحديث الموقع بنجاح']);}catch(PDOException $e){http_response_code(500);echo json_encode(['error'=>'خطأ في تحديث الموقع: '.$e->getMessage()]);}}
function bulkScanBaggage($pdo,$i){if(!isset($i['baggage_ids'])||!is_array($i['baggage_ids'])){http_response_code(400);echo json_encode(['error'=>'baggage_ids يجب أن يكون مصفوفة']);return;}foreach(['location_id','status'] as $f){if(!isset($i[$f])||empty($i[$f])){http_response_code(400);echo json_encode(['error'=>"الحقل $f مطلوب"]);return;}}try{$pdo->beginTransaction();$count=0;$errors=[];foreach($i['baggage_ids'] as $id){try{$s=$pdo->prepare("UPDATE baggage SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?");$s->execute([$i['status'],$id]);$s=$pdo->prepare("INSERT INTO tracking_logs (baggage_id,location_id,status,remarks,scanned_by,device_id,scan_type,actual_scan_time) VALUES (?,?,?,?,?,?,?,NOW())");$s->execute([$id,$i['location_id'],$i['status'],$i['remarks']??'مسح جماعي',$_SESSION['user_id'],$i['device_id']??null,$i['scan_type']??'manual']);$count++;}catch(PDOException $e){$errors[]="خطأ في معالجة الأمتعة $id: ".$e->getMessage();}}$pdo->commit();echo json_encode(['success'=>true,'message'=>"تم معالجة $count أمتعة بنجاح",'processed_count'=>$count,'errors'=>$errors]);}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo json_encode(['error'=>'خطأ في المسح الجماعي: '.$e->getMessage()]);}}
function updateTrackingStatus($pdo,$i){foreach(['tracking_id','status'] as $f){if(!isset($i[$f])||empty($i[$f])){http_response_code(400);echo json_encode(['error'=>"الحقل $f مطلوب"]);return;}}try{$s=$pdo->prepare("UPDATE tracking_logs SET status=?,remarks=?,updated_at=CURRENT_TIMESTAMP WHERE id=?");$s->execute([$i['status'],$i['remarks']??'',$i['tracking_id']]);if($s->rowCount()>0)echo json_encode(['success'=>true,'message'=>'تم تحديث حالة التتبع بنجاح']);else{http_response_code(404);echo json_encode(['error'=>'لم يتم العثور على سجل التتبع']);}}catch(PDOException $e){http_response_code(500);echo json_encode(['error'=>'خطأ في تحديث حالة التتبع: '.$e->getMessage()]);}}
?>